<template><div v-if="open" class="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/40 p-3"><div class="w-full max-w-2xl max-h-[88vh] overflow-hidden border border-slate-200 bg-white shadow-lg"><div class="flex items-center justify-between border-b border-slate-200 px-4 py-2.5"><div><p class="text-[10px] font-semibold uppercase tracking-wide text-primary">Offplan financing</p><h2 class="text-sm font-semibold text-slate-900">New bank financing</h2></div><button @click="close" class="h-7 w-7 border border-slate-300 text-sm">×</button></div><form @submit.prevent="submit"><div class="grid max-h-[calc(88vh-112px)] gap-2 overflow-y-auto p-3 md:grid-cols-2"><Field v-for="f in textFields" :key="f" :label="label(f)"><input v-model="form[f]" class="input"/></Field><Field label="Loan term months"><input v-model.number="form.loan_term_months" type="number" min="1" class="input"/></Field><Field label="Loan status"><select v-model="form.loan_status" class="input"><option v-for="s in loanStatuses" :key="s" :value="s">{{s}}</option></select></Field><Field label="Approved at"><input v-model="form.approved_at" type="datetime-local" class="input"/></Field><Field label="First payment date"><input v-model="form.first_payment_date" type="date" class="input"/></Field><Field label="Application"><div class="application-select"><input :value="applicationSearch" @focus="$event.target.select();applicationDropdownOpen=true" @input="applicationSearch=$event.target.value;searchApplications()" @keydown.esc="applicationDropdownOpen=false" @keydown.down.prevent="applicationDropdownOpen=true" placeholder="Search customer or select an application..." class="input application-search"/><div v-if="applicationDropdownOpen" class="application-menu"><button type="button" class="application-option" @mousedown.prevent="selectApplication(null)">Select application</button><button v-for="a in filteredApplications()" :key="a.id" type="button" class="application-option" @mousedown.prevent="selectApplication(a)">{{applicationLabel(a)}}</button><p v-if="filteredApplications().length===0" class="application-empty">No applications found</p></div></div></Field></div><div v-if="error" class="mx-3 mb-2 flex h-7 items-center overflow-hidden border border-red-200 bg-red-50 px-2 text-[10px] text-red-700" :title="error">{{error}}</div><div class="flex justify-end gap-2 border-t border-slate-200 px-3 py-2"><button type="button" @click="close" class="border border-slate-300 px-3 py-1.5 text-xs">Cancel</button><button :disabled="loading" class="bg-primary px-3 py-1.5 text-xs font-semibold text-white">{{loading?'Saving…':'Create financing'}}</button></div></form></div></div></template>
<script>
import OffplanField from "../offplan property/OffplanField.vue";
const blank=()=>({bank_name:"",loan_account_number:"",loan_amount:"",interest_rate:"",loan_term_months:0,monthly_payment:"",loan_status:"pending",approved_at:"",first_payment_date:"",notes:"",application:0});
export default{name:"AddOffplanBankFinancing",components:{Field:OffplanField},props:{open:Boolean},data(){return{form:blank(),applications:[],applicationSearch:"",searchResults:[],searchRequest:0,applicationDropdownOpen:false,loading:false,error:"",textFields:["bank_name","loan_account_number","loan_amount","interest_rate","monthly_payment","notes"],loanStatuses:["pending","approved","rejected","active","completed","cancelled"]}},watch:{open(v){if(v){this.form=blank();this.applicationSearch="";this.searchResults=[];this.error="";this.loadApplications()}}},methods:{label(v){return v.replace(/_/g," ").replace(/\b\w/g,c=>c.toUpperCase())},personName(v){if(!v)return"—";if(typeof v==="string")return v;return[v.first_name,v.middle_name,v.last_name].filter(Boolean).join(" ")||v.full_name||v.name||v.username||v.phone_number||v.phone||"—"},propertyName(p){if(!p||typeof p!=="object")return"Offplan property";const z=p.property_zone||p.zone;return z?.name||p.name||p.title||p.property_name||p.developer||p.property_type||"Offplan property"},applicationLabel(a){const p=(a?.payment_product?.offplan_property&&typeof a.payment_product.offplan_property==="object")?a.payment_product.offplan_property:(a?.offplan_property&&typeof a.offplan_property==="object"?a.offplan_property:null);const customer=this.personName(a?.customer);const property=this.propertyName(p);const zone=p?.property_zone?.name;return `Application #${a?.id} • ${customer} • ${property}${zone&&zone!==property?" ("+zone+")":""} • ${a?.application_status||"status unknown"}`},selectApplication(a){this.form.application=a?Number(a.id):0;this.applicationSearch=a?this.applicationLabel(a):"";this.applicationDropdownOpen=false},filteredApplications(){const q=(this.applicationSearch||"").trim().toLowerCase();const byId=new Map([...this.applications,...this.searchResults].map(a=>[a.id,a]));return Array.from(byId.values()).filter(a=>{if(!q)return true;const customer=this.personName(a?.customer);return customer.toLowerCase().includes(q)||(a?.customer?.phone_number||"").toLowerCase().includes(q)||String(a?.id||"").includes(q)})},async searchApplications(){const q=(this.applicationSearch||"").trim();const request=++this.searchRequest;if(!q){this.searchResults=[];return}try{const r=await this.$apiGet(`/get_offplan_product_applications?search=${encodeURIComponent(q)}`);if(request!==this.searchRequest)return;const d=r?.data?.data||r?.data||r?.applications||r;const results=Array.isArray(d)?d:(d?.results||d?.applications||[]);this.searchResults=results.length?results:[]}catch(e){if(request===this.searchRequest)this.searchResults=[]}},async loadApplications(){try{const r=await this.$apiGet("/get_offplan_product_applications");const d=r?.data?.data||r?.data||r?.applications||r;this.applications=Array.isArray(d)?d:(d?.results||d?.applications||[])}catch(e){this.error=e?.message||"Unable to load applications."}},close(){if(!this.loading)this.$emit("close")},async submit(){this.loading=true;this.error="";try{await this.$apiPost("/post_offplan_bank_financing",{...this.form,loan_term_months:Number(this.form.loan_term_months),application:Number(this.form.application)});this.$emit("saved");this.$emit("close")}catch(e){this.error=e?.message||"Unable to create financing."}finally{this.loading=false}}}};
</script>
<style scoped>.input{width:100%;border:1px solid #cbd5e1;padding:.4rem .55rem;font-size:.75rem;line-height:1rem;outline:none;background:#fff}.input:focus{border-color:#5f5ffc}.application-select{display:flex;flex-direction:column;gap:.25rem}.application-search{border-bottom-left-radius:0;border-bottom-right-radius:0}.application-menu{position:relative;z-index:20;max-height:12rem;overflow-y:auto;border:1px solid #cbd5e1;border-top:0;background:#fff;box-shadow:0 4px 8px #00000012}.application-option{display:block;width:100%;padding:.45rem .55rem;text-align:left;font-size:.75rem;color:#334155;background:#fff}.application-option:hover,.application-option:focus{background:#f1f5f9;outline:none}.application-empty{padding:.5rem;font-size:.75rem;color:#64748b}</style>